import AppKit

/// The Camera Log popup's Use LUT… (spec §11 GR-16): a `.cube` chosen in a
/// sheet panel becomes the selected video file's input conversion — Import
/// LUT…'s panel and probe (`EditorViewController+Look.swift`), then ONE
/// grouped edit "Camera Log": `add_media` (a file already in the list is
/// the row it already has) and `set_media_color {lut}`. The agent's mirror is
/// `import_media` then `set_media_color`.
extension EditorViewController {
    @objc func useCameraLogLUT(_ sender: Any?) {
        guard let document = document, let window = view.window,
            let media = document.selectedMedia,
            document.project.snapshot.media(media)?.kind == .video
        else {
            NSSound.beep()
            return
        }
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.allowedContentTypes = [MediaImporter.lutType]
        panel.message = "Choose a .cube LUT that converts this file's log footage to Rec. 709."
        panel.beginSheetModal(for: window) { response in
            guard response == .OK, let url = panel.url else { return }
            Self.useCameraLogLUT(from: url, into: document, media: media)
        }
    }

    /// The probe, then the one grouped step; off-event, so grouped
    /// explicitly. A refused file is the document's error sheet.
    static func useCameraLogLUT(from url: URL, into document: ProjectDocument, media: UInt32) {
        MediaImporter.probe(url: url, mayAsk: true) { result in
            do {
                let descriptor = try result.get()
                guard let lut = try backgroundMedia(for: descriptor, in: document.project) else {
                    NSSound.beep()
                    return
                }
                // The media's PQ peak override is kept (spec §11 HD-12).
                let pq = document.project.snapshot.media(media)?.color?.pq
                document.performGroupedEdit(
                    "Camera Log",
                    [.addMedia(descriptor: descriptor),
                     .setMediaColor(media: media, color: MediaColor(lut: lut, pq: pq))])
            } catch {
                document.present(error)
            }
        }
    }
}
import AppKit

/// What the Camera Log popup can say: none, a built-in curve with its gamut,
/// a `lut` media of the project, or the Use LUT… row that imports one.
enum CameraLogChoice: Equatable {
    case none
    case curve(LogCurve, CameraGamut)
    case lut(UInt32)
    case useLUT

    /// The built-in rows, in the popup's order (spec §11 GR-16): every curve
    /// with each gamut it pairs with.
    static let curves: [CameraLogChoice] = [
        .curve(.appleLog, .bt2020), .curve(.appleLog2, .appleWideGamut),
        .curve(.slog3, .sGamut3Cine), .curve(.slog3, .sGamut3), .curve(.vlog, .vGamut),
        .curve(.canonLog2, .cinemaGamut), .curve(.canonLog2, .bt2020),
        .curve(.canonLog3, .cinemaGamut), .curve(.canonLog3, .bt2020),
    ]

    /// A media's setting as a row: its curve and gamut (the curve's first
    /// when none is stored), else its LUT, else none.
    init(_ color: MediaColor?) {
        if let log = color?.log, let gamut = color?.effectiveGamut {
            self = .curve(log, gamut)
        } else if let lut = color?.lut {
            self = .lut(lut)
        } else {
            self = .none
        }
    }

    /// The row's title: "S-Log3 / S-Gamut3.Cine", "Apple Log" (a curve with
    /// one gamut is named alone), "LUT: <name>".
    func title(in snapshot: ProjectSnapshot) -> String {
        switch self {
        case .none: return "None"
        case .curve(let log, let gamut):
            return log.gamuts.count > 1 || log == .vlog
                ? "\(log.displayName) / \(gamut.displayName)" : log.displayName
        case .lut(let id):
            return "LUT: " + (snapshot.media(id).map(LookGallery.lutName) ?? "media \(id)")
        case .useLUT: return "Use LUT…"
        }
    }
}

/// The Media tab's **Camera Log** section (spec §11 GR-16, §4.3): how the
/// file selected in the list is converted at step 0 — None, a maker's curve,
/// or a `.cube` LUT — one undo step "Camera Log", and a line saying what is
/// set and whether it came from the file. It acts on `selectedMedia`, the row
/// a click selects (`MediaPaneCommands.select(_:)`, which refreshes this
/// section), and is disabled when that is not a video file. The agent's
/// mirror is `set_media_color` (`AgentServer+Media.swift`).
extension MediaPane {
    func cameraLogSection() -> InspectorSection {
        let binding = self.binding
        /// The selected row when it is a video file.
        func selected() -> MediaSnapshot? {
            guard let id = binding.document?.selectedMedia,
                let media = binding.documentSnapshot.media(id), media.kind == .video
            else { return nil }
            return media
        }
        let snapshot = binding.documentSnapshot
        let luts = LookGallery.luts(in: snapshot).map { CameraLogChoice.lut($0.id) }
        let choices = ([CameraLogChoice.none] + CameraLogChoice.curves + luts + [.useLUT])
            .map { (title: $0.title(in: snapshot), value: $0) }
        let popup = OptionPopupControl(
            width: InspectorMetrics.popupWidth + 52, choices: choices,
            read: { CameraLogChoice(selected()?.color) },
            write: { [weak self] choice in
                guard let media = selected(), choice != CameraLogChoice(media.color) else { return }
                // Every write keeps a PQ file's peak override (spec §11 HD-12):
                // `color` replaces the Camera Log and the override together.
                let pq = media.color?.pq
                switch choice {
                case .none:
                    binding.apply(
                        "Camera Log", [.setMediaColor(media: media.id, color: MediaColor(pq: pq))])
                case .curve(let log, let gamut):
                    binding.apply(
                        "Camera Log",
                        [.setMediaColor(
                            media: media.id, color: MediaColor(log: log, gamut: gamut, pq: pq))])
                case .lut(let lut):
                    binding.apply(
                        "Camera Log",
                        [.setMediaColor(media: media.id, color: MediaColor(lut: lut, pq: pq))])
                case .useLUT:
                    self?.inspector?.onCommand?(
                        #selector(EditorViewController.useCameraLogLUT(_:)))
                }
            },
            enabled: { selected() != nil },
            onEdit: { binding.edited() })
        popup.toolTip = "How this file's log footage is converted to Rec. 709"
        let readout = inspectorReadout(width: InspectorMetrics.popupWidth + 52) {
            guard let media = selected() else { return "Select a video in the list" }
            let title = CameraLogChoice(media.color).title(in: binding.documentSnapshot)
            return media.color?.detected == true ? "\(title) — from the file" : title
        }
        return InspectorSection(
            id: "media.camera_log", title: "Camera Log",
            summary: {
                selected().map {
                    CameraLogChoice($0.color).title(in: binding.documentSnapshot)
                }
            },
            rows: [inspectorRow("Log", [popup]), inspectorRow(nil, [readout])])
    }
}
import AppKit

/// The Media tab's **HDR10** section (spec §11 HD-12, §4.3): the peak of the
/// PQ file selected in the list — what import read from its HDR10 metadata,
/// which places step 0's PQ shoulder — with a Peak field that overrides it, a
/// Use File's button that clears the override, and a line saying where the
/// peak came from; one undo step "PQ Peak". It is there once the project has
/// a PQ file (`MediaPane.makeSections`), acts on `selectedMedia`, the row a
/// click selects, and is disabled when that is not a PQ file. Every write
/// keeps the media's Camera Log, as the Camera Log section's writes keep the
/// peak. The agent's mirror is `set_media_color {peak}`
/// (`AgentServer+Media.swift`).
extension MediaPane {
    func hdr10Section() -> InspectorSection {
        let binding = self.binding
        /// The selected row when it is a PQ file: a video or a still (spec §11
        /// HD-20 (b)).
        func selected() -> MediaSnapshot? {
            guard let id = binding.document?.selectedMedia,
                let media = binding.documentSnapshot.media(id),
                media.kind == .video || media.kind == .image,
                media.color?.pq != nil
            else { return nil }
            return media
        }
        /// The override set to `peak` (nil: the file's), the Camera Log kept.
        func write(_ media: MediaSnapshot, peak: UInt32?) {
            guard var color = media.color, var pq = color.pq, pq.peak != peak else { return }
            pq.peak = peak
            color.pq = pq
            binding.apply("PQ Peak", [.setMediaColor(media: media.id, color: color)])
        }
        let field = OptionFieldControl(
            width: InspectorMetrics.wideFieldWidth + 14, unit: "cd/m²", decimals: 0,
            min: 1, max: 10_000, quick: [1000, 2000, 4000, 10_000],
            read: {
                Double(selected()?.color?.pq?.effectivePeak
                    ?? UInt32(InputConversions.pqWhite))
            },
            write: { value in
                guard let media = selected(), let pq = media.color?.pq else { return }
                let peak = UInt32(max(1, min(10_000, value.rounded())))
                // The value already shown is no new choice.
                guard peak != pq.effectivePeak else { return }
                write(media, peak: peak)
            },
            enabled: { selected() != nil },
            onEdit: { binding.edited() })
        field.toolTip = "The brightness this file's highlights roll off to white at"
        let useFile = OptionButtonControl(
            title: "Use File's",
            action: {
                guard let media = selected() else { return }
                write(media, peak: nil)
            },
            enabled: { selected()?.color?.pq?.peak != nil },
            onEdit: { binding.edited() })
        useFile.toolTip = "Go back to the peak the file's HDR10 metadata names"
        let readout = inspectorReadout(width: InspectorMetrics.popupWidth + 52) {
            guard let pq = selected()?.color?.pq else { return "Select a PQ file in the list" }
            return MediaPane.hdr10Line(pq)
        }
        return InspectorSection(
            id: "media.hdr10", title: "HDR10",
            summary: {
                selected()?.color?.pq.map {
                    "\(MediaPane.nits($0.effectivePeak ?? UInt32(InputConversions.pqWhite))) cd/m²"
                }
            },
            rows: [inspectorRow("Peak", [field, useFile]), inspectorRow(nil, [readout])])
    }

    /// Where a PQ file's peak came from, in the readout's words.
    static func hdr10Line(_ pq: PQColor) -> String {
        let file = pq.file.map { "\(nits($0)) cd/m²" }
        let field = pq.from.map { $0 == .maxCLL ? "MaxCLL" : "mastering display" }
        if pq.peak != nil {
            guard let file else { return "Set by hand; the file has no HDR10 metadata" }
            return "Set by hand; the file says \(file)" + (field.map { " (\($0))" } ?? "")
        }
        guard let file else {
            return "No HDR10 metadata — \(nits(UInt32(InputConversions.pqWhite))) cd/m² assumed"
        }
        return "Mastered at \(file) (" + (field.map { "\($0), " } ?? "") + "from the file)"
    }

    /// A whole number of cd/m² with thousands grouped by commas ("4,000"),
    /// whatever the locale, as the spec writes them.
    static func nits(_ value: UInt32) -> String {
        let digits = String(value)
        var out = ""
        for (index, digit) in digits.enumerated() {
            if index > 0, (digits.count - index) % 3 == 0 { out.append(",") }
            out.append(digit)
        }
        return out
    }
}
import Foundation

// MARK: - Camera log (spec §11 GR-16)

/// A maker's published log curve, as `media.color.log` spells it. Apple
/// Log 2 is Apple Log's curve with Apple Wide Gamut (GR-16's append); Canon
/// Log 2 and 3 pair with Cinema Gamut or BT.2020 (spec §11 HD-17).
enum LogCurve: String, Codable, CaseIterable {
    case appleLog = "apple_log", slog3, vlog, appleLog2 = "apple_log2"
    case canonLog2 = "canon_log2", canonLog3 = "canon_log3"

    /// The gamuts the curve pairs with, its default first — the core's
    /// `LogCurve::gamuts`, which refuses any other.
    var gamuts: [CameraGamut] {
        switch self {
        case .appleLog: return [.bt2020]
        case .appleLog2: return [.appleWideGamut]
        case .slog3: return [.sGamut3Cine, .sGamut3]
        case .vlog: return [.vGamut]
        case .canonLog2, .canonLog3: return [.cinemaGamut, .bt2020]
        }
    }

    var displayName: String {
        switch self {
        case .appleLog: return "Apple Log"
        case .appleLog2: return "Apple Log 2"
        case .slog3: return "S-Log3"
        case .vlog: return "V-Log"
        // "C-Log": "Canon Log 3 / Cinema Gamut" is wider than the popup (HD-17 (b)).
        case .canonLog2: return "C-Log2"
        case .canonLog3: return "C-Log3"
        }
    }
}

/// The camera gamut a log curve's signal is in, as `media.color.gamut`
/// spells it.
enum CameraGamut: String, Codable, CaseIterable {
    case bt2020, sGamut3Cine = "s_gamut3_cine", sGamut3 = "s_gamut3", vGamut = "v_gamut"
    case appleWideGamut = "apple_wide_gamut"
    case cinemaGamut = "cinema_gamut"

    var displayName: String {
        switch self {
        case .bt2020: return "BT.2020"
        case .sGamut3Cine: return "S-Gamut3.Cine"
        case .sGamut3: return "S-Gamut3"
        case .vGamut: return "V-Gamut"
        case .appleWideGamut: return "Apple Wide Gamut"
        case .cinemaGamut: return "Cinema Gamut"
        }
    }
}

// MARK: - The PQ peak (spec §11 HD-12)

/// Which HDR10 field gave a PQ file's peak, as `media.color.pq.from` spells
/// it: CTA-861.3's MaxCLL, or SMPTE ST 2086's mastering maximum.
enum PeakSource: String, Codable, CaseIterable {
    case maxCLL = "max_cll", masteringDisplay = "mastering_display"
}

/// A PQ file's HDR10 peak, `media.color.pq`: `file`, what import read in
/// whole cd/m², with `from` naming its field; `peak`, the person's override.
/// The core wrote it, so it decodes leniently (`init(from:)` below).
struct PQColor: Codable, Equatable {
    var file: UInt32?
    var from: PeakSource?
    var peak: UInt32?

    /// The peak step 0 uses: the override, else the file's; nil means
    /// `InputConversions.pqWhite`.
    var effectivePeak: UInt32? { peak ?? file }

    /// The stored shape, each key only when set.
    var dictionary: [String: Any] {
        var d: [String: Any] = [:]
        if let file = file { d["file"] = file }
        if let from = from { d["from"] = from.rawValue }
        if let peak = peak { d["peak"] = peak }
        return d
    }
}

extension PQColor {
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.init(file: c.lenient(.file), from: c.lenient(.from), peak: c.lenient(.peak))
    }
}

// MARK: - The media's colour

/// A video media's Camera Log: a built-in curve and its gamut, or a `lut`
/// media converting the file instead; `detected` when import read it from
/// the file's label; `pq` a PQ file's peak (spec §11 HD-12). Also a recipe
/// layer's and a plan segment's `input`, which carry no `detected` and no
/// `pq` but a flat `peak` (the effective one) — so the decoder is written
/// out: a synthesized one would throw on the absent key, and `lenient` would
/// read that as no setting at all.
struct MediaColor: Codable, Equatable {
    var log: LogCurve?
    var gamut: CameraGamut?
    var lut: UInt32?
    var detected: Bool
    /// The stored peak record; nil on every media that is not a PQ file.
    var pq: PQColor?
    /// An `input`'s effective PQ peak; never stored.
    var peak: UInt32?

    init(log: LogCurve? = nil, gamut: CameraGamut? = nil, lut: UInt32? = nil,
         detected: Bool = false, pq: PQColor? = nil, peak: UInt32? = nil) {
        self.log = log
        self.gamut = gamut
        self.lut = lut
        self.detected = detected
        self.pq = pq
        self.peak = peak
    }

//! Camera log on a media (spec §11 GR-16): `set_media_color`, the rules a
//! `media.color` obeys, and what the recipe and the plan publish of it —
//! written once for every door that meets it.
//!
//! - **The op.** `set_media_color {media, color}` sets a video media's
//!   setting, or clears it with `color: null` (an identity when there is
//!   none). `color` is read strictly ([`read_color`]): an object or `null`,
//!   only the keys `log`, `gamut`, `lut`, `peak`, `detected` and `pq`, each
//!   through serde's own vocabulary. `detected` and `pq` are import's to
//!   write, so the op refuses them; what the op stores always has `detected:
//!   false`, and an absent `gamut` is stored as the curve's first
//!   ([`LogCurve::gamuts`]). `peak` is a PQ file's override (spec §11 HD-12):
//!   `color` replaces the Camera Log and the override together, import's
//!   reading (`pq.file`, `pq.from`) survives every op, and `null` clears
//!   both, keeping the reading.
//! - **The rules** ([`Project::check_media_color`]), each its own sentence:
//!   the media is a video file, or an image whose colour is a PQ still's
//!   `pq` alone (spec §11 HD-20 (b)); the setting has `log` or `lut`, not both, or
//!   is a PQ file's `pq` alone; `gamut` goes with `log` and is one its curve
//!   takes; `lut` names a `lut` media of the project; `pq`'s peaks are within
//!   [`PEAK_MIN`]–[`PEAK_MAX`] and `from` goes with `file`. The op answers
//!   them as refusals; `add_media` (whose descriptor may carry a detected
//!   `color`) and `validate` (a file) as errors, as they answer every other
//!   field. The op's own: a `peak` only on a PQ file and in range, an image
//!   taking only a `peak` alone, and an asked `color` with none of `log`,
//!   `lut` and `peak` refused.
//! - **What draws** ([`Project::media_input`]): the recipe layer of a media
//!   or still source and the plan's video segment publish the setting as
//!   `input` — `{log, gamut}` or `{lut}`, and `peak` (the effective PQ peak)
//!   beside either or alone — and the app converts at step 0. The recipe
//!   layer of an image source publishes a PQ still's `{peak}` alone (spec
//!   §11 HD-20 (b)), and `null` for `{pq: {}}`. A `lut` that names no `lut`
//!   media publishes nothing of it.
//! - **Removing a LUT** that converts a media (`lut.rs`'s `remove_lut`) is
//!   refused naming those media ([`Project::media_converted_by`]), or with
//!   `with_clips` clears the conversions with the looks.

use serde_json::{Map, Value};

use crate::export::describe;
use crate::export_overrides::spelled;
use crate::model::{Media, MediaColor, MediaKind, Project};
use crate::model_media_color::{PqColor, PEAK_MAX, PEAK_MIN};
use crate::outcome::Outcome;

/// The keys a `color` may carry: the setting's, `peak` (the op's alone), and
/// the two import writes, which the op refuses by name.
const COLOR_KEYS: [&str; 6] = ["log", "gamut", "lut", "peak", "detected", "pq"];

/// An asked `color`: the Camera Log as the model spells it, and `peak`.
struct Asked {
    color: MediaColor,
    peak: Option<i64>,
}

/// A media kind as a sentence names it: "an audio file", "an image", "a LUT".
fn kind_phrase(kind: MediaKind) -> &'static str {
    match kind {
        MediaKind::Video => "a video file",
        MediaKind::Audio => "an audio file",
        MediaKind::Image => "an image",
        MediaKind::Lut => "a LUT",
    }
}

/// The sentence for a setting with nothing to convert by.
const NEEDS_LOG_OR_LUT: &str = "color needs log or lut; null clears it";

/// A colour is a setting on a video file; on an image only when `image_ok`
/// (a PQ still's peak alone, spec §11 HD-20 (b)), and every other kind never.
fn check_kind(media: &Media, image_ok: bool) -> Result<(), String> {
    if media.kind == MediaKind::Video || (media.kind == MediaKind::Image && image_ok) {
        return Ok(());
    }
    Err(format!(
        "media {} is {}; Camera Log is a setting on a video file",
        media.id,
        kind_phrase(media.kind)
    ))
}

/// A stored `pq` (spec §11 HD-12): `file` and `peak` within
/// [`PEAK_MIN`]–[`PEAK_MAX`], and `from` present exactly when `file` is.
fn check_pq(pq: PqColor) -> Result<(), String> {
    for (key, value) in [("file", pq.file), ("peak", pq.peak)] {
        if let Some(n) = value.filter(|n| !(PEAK_MIN..=PEAK_MAX).contains(n)) {
            return Err(format!(
                "color.pq.{key} must be {PEAK_MIN}–{PEAK_MAX} cd/m², not {n}"
            ));
        }
    }
    if pq.file.is_some() != pq.from.is_some() {
        return Err("color.pq.from goes with color.pq.file".to_string());
    }
    Ok(())
}

/// `color` read strictly: `None` for `null`, else the setting and `peak`, or
/// the `Err` naming what is wrong — not an object, an unknown key, a `peak`
/// that is not a whole number, or a value serde refuses (its own sentence,
/// naming the variants).
fn read_color(color: &Value) -> Result<Option<Asked>, String> {
    let fields = match color {
        Value::Null => return Ok(None),
        Value::Object(fields) => fields,
        other => {
            return Err(format!(
                "color must be a json object or null, not {}",
                describe(other)
            ))
        }
    };
    if let Some(key) = fields
        .keys()
        .find(|key| !COLOR_KEYS.contains(&key.as_str()))
    {
        return Err(format!("unknown key \"{key}\" in color"));
    }
    let peak = match fields.get("peak") {
        None => None,
        Some(value) => Some(value.as_i64().ok_or_else(|| {
            format!(
                "color.peak must be a whole number of cd/m², not {}",
                describe(value)
            )
        })?),
    };
    let mut setting = fields.clone();
    setting.remove("peak");
    serde_json::from_value(Value::Object(setting))
        .map(|color| Some(Asked { color, peak }))
        .map_err(|e| format!("color does not match the schema: {e}"))
}

impl Project {
    /// Sets or clears a video media's camera-log setting (spec §11 GR-16)
    /// and a PQ file's peak override (HD-12). `Err` for an unknown media or
    /// an unreadable `color`; a refusal, in the rule's own sentence, for
    /// `detected`, `pq`, a `peak` out of range or on a file that is not PQ,
    /// an asked `color` with none of `log`, `lut` and `peak`, or a setting
    /// [`Project::check_media_color`] refuses.
    pub(crate) fn set_media_color(&self, media: u32, color: &Value) -> Result<Outcome, String> {
        let current = self.require_media(media)?.color;
        // Import's reading, kept by every op: `pq` without the override.
        let reading = current
            .and_then(|c| c.pq)
            .map(|pq| PqColor { peak: None, ..pq });
        let stored = match read_color(color)? {
            None => reading.map(|pq| MediaColor {
                pq: Some(pq),
                ..MediaColor::default()
            }),
            Some(asked) => match self.asked_color(media, asked, reading) {
                Ok(setting) => Some(setting),
                Err(why) => return Ok(Outcome::Refused(why)),
            },
        };
        let mut next = self.clone();
        let Some(row) = next.media.iter_mut().find(|m| m.id == media) else {
            return Err(format!("no media with id {media}"));
        };
        row.color = stored;
        if stored.is_some() {
            if let Err(why) = self.check_media_color(row) {
                return Ok(Outcome::Refused(why));
            }
        }
        self.finish(next)
    }

    /// The setting an asked `color` stores on `media` beside its `reading`,
    /// or (`Err`) the refusal in the rule's own sentence, in this order: `detected`,
    /// `pq`, a `peak` outside [`PEAK_MIN`]–[`PEAK_MAX`] or on media that is
    /// not a PQ file, the media's kind (an image passes only with a `peak`
    /// alone, spec §11 HD-20 (b)), and none of `log`, `lut` and `peak`.
    fn asked_color(
        &self,
        media: u32,
        asked: Asked,
        reading: Option<PqColor>,
    ) -> Result<MediaColor, String> {
        let given = asked.color;
        if given.detected {
            return Err("color.detected is written by import, not set".to_string());
        }
        if given.pq.is_some() {
            return Err("color.pq is read from the file at import, not set".to_string());
        }
        let peak = match asked.peak {
            None => None,
            Some(n) => match u32::try_from(n) {
                Ok(n) if (PEAK_MIN..=PEAK_MAX).contains(&n) => Some(n),
                _ => {
                    return Err(format!(
                        "color.peak must be {PEAK_MIN}–{PEAK_MAX} cd/m², not {n}"
                    ))
                }
            },
        };
