//! stored one, so a probe without one clears it, and no probe keeps it. A
//! probe never carries `color`, and a relink keeps the media's Camera Log
//! (spec §11 GR-16): it is the person's reading of the footage, which a new
//! path to the same footage does not change. A probe's `cursor` replaces the
//! stored one as `original` does (spec §11 CU-39). A probe never carries `speech`
//! either; a probed relink clips the stored spans to the new file or clears
//! them (spec §11 AU-116).
//!
//! Cut out of `edit_track.rs`, which keeps the media list's other two ops
//! and the two things this one shares with `add_media`: `MEDIA_KEYS` and
//! `check_media_fields`, so a probe is checked in the same words a
//! descriptor is.

use std::mem;

use serde_json::Value;

use crate::edit_track::{check_media_fields, normalize_original, MEDIA_KEYS};
use crate::export::describe;
    ///
    /// A `bookmark` of `None` CLEARS the stored one rather than keeping it:
    /// a bookmark resolves to the file it was made from, so the old one
    /// would point straight back at the file the user is replacing.
    ///
    /// Answers, in order: `Err` for an unknown media or an empty path; `Err`
    /// for a probe that is not an object, that carries a key outside the
    /// descriptor's (or `path` or `bookmark`, which are this op's own
    /// arguments, or `color`, which a relink keeps), that does not match the
    /// schema, or whose fields
    /// `add_media` would refuse; then a REFUSAL for a file of another kind,
    /// because each clip's source kind was chosen from it.
    ///
    /// A probed relink writes `duration`, `width`, `height`, `fps`, the
    /// three flags and `original` (none in the probe clears it), then
    /// holds each `media`-source clip of this media — on the timeline and
    /// in every stored nest, orphans included — whose
    /// duration exceeds the window the file now holds to
    /// `duration_resnapped` (D4-4): on the grid, at least one frame, the
    /// frame floor winning for a clip whose `in` is past the new end.
    /// Everything else on the clip is kept, as `trim_end` keeps it; a still
/// wrong with it — the Interfaces order of spec §11 #63: not an object, an
/// unknown key, the schema, then `add_media`'s field checks.
fn read_probe(media: u32, path: &str, probe: &Value) -> Result<Media, String> {
    let Value::Object(fields) = probe else {
        return Err(format!(
            "a relink probe must be a json object, not {}",
            describe(probe)
        ));
    };
    for key in fields.keys() {
        if !MEDIA_KEYS.contains(&key.as_str())
            || key == "path"
            || key == "bookmark"
            || key == "color"
        {
            return Err(format!("unknown key \"{key}\" in a relink probe"));
        }
    }
    // Deserialized through `Media` itself, as `add_media` does, so the
    // probe's schema is the model's schema with no second spelling of it.
    let mut record = fields.clone();
    record.insert("id".to_string(), Value::from(media));
    record.insert("path".to_string(), Value::from(path));
    let mut record: Media = serde_json::from_value(Value::Object(record))
        .map_err(|e| format!("relink probe does not match the schema: {e}"))?;
    record.original = normalize_original(record.original);
    check_media_fields(&record)?;
    Ok(record)
}

//! An HLG project's deliverables (spec §11 HD-5, HD-14): which picture an
//! export row writes — the HLG master, HDR10 (PQ) or the SDR version — and the
//! two refusals that keep a file from carrying a picture it cannot label.
//!
//! The vocabulary is three words, `hlg`, `pq` and `sdr`, spelled
//! `dynamic_range` both as an export override (`export_overrides.rs` reads it)
//! and as a recipe option (`recipe_options.rs`), because the two are one
//! decision seen from two sides: the export publishes its settings' `color` as
//! the recipe option of the key it draws, so the output pass the preview draws
//! for Show SDR Version is the one the file is written through.
//!
//! An SDR project is untouched by all of it: `deliverable` answers `None` for
//! every row there, so its settings carry no `color` and its recipes no
//! `dynamic_range`, and every SDR file and frame is the text and the bytes it
//! was.

use crate::export_table::Preset;
use crate::model::{CanvasOutput, Project};

/// The picture an HLG project's export or frame is drawn as (spec §11 HD-14).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DynamicRange {
    /// The working space itself, BT.2100 HLG: no output pass.
    Hlg,
    /// HDR10: the HLG display light at 1,000 cd/m² through ST 2084.
    Pq,
    /// The SDR version (spec §11 HD-4): the inverse of the lift with a
    /// shoulder above reference white, encoded Rec. 709.
    Sdr,
}

impl DynamicRange {
    /// The word for `text`, or `None` for anything else.
    pub fn parse(text: &str) -> Option<DynamicRange> {
        match text {
            "hlg" => Some(DynamicRange::Hlg),
            "pq" => Some(DynamicRange::Pq),
            "sdr" => Some(DynamicRange::Sdr),
            _ => None,
        }
    }

    /// The word as it is spelled in JSON.
    pub fn as_str(self) -> &'static str {
        match self {
            DynamicRange::Hlg => "hlg",
            DynamicRange::Pq => "pq",
            DynamicRange::Sdr => "sdr",
        }
    }
}

/// The rows that carry an HDR picture (spec §11 HD-5, CX-14, CX-15, CX-16):
/// the six HDR rows, each 10-bit for an HDR picture (`vp9_webm` is 8-bit only
/// at `sdr`). Every other video row of an HLG project writes the SDR version.
pub(crate) const HDR_ROWS: [&str; 6] = [
    "hevc_10bit",
    "av1",
    "av1_webm",
    "vp9_webm",
    "prores_422",
    "prores_4444",
];

impl Project {
    /// What `preset` writes for this project when `asked` was requested
    /// (spec §11 HD-14 (c)): `None` for an audio row and for every row of an
    /// SDR project (nothing to label), else the resolved picture. An audio row
    /// reads the argument and ignores it, as a bitrate on a GIF is; an SDR
    /// project takes `sdr` as nothing; `hlg` and `pq` are refused in an SDR
    /// project and on a row that is not 10-bit, each in its own sentence.
    pub(crate) fn deliverable(
        &self,
        preset: &Preset,
        asked: Option<DynamicRange>,
    ) -> Result<Option<DynamicRange>, String> {
        if !preset.video {
            return Ok(None);
        }
        let hdr_asked = asked.filter(|range| *range != DynamicRange::Sdr);
        if self.canvas.output != CanvasOutput::Hlg {
            return match hdr_asked {
                Some(range) => Err(format!(
                    "dynamic_range \"{}\" needs an HLG project; set_canvas output \"hlg\" first",
                    range.as_str()
                )),
                None => Ok(None),
            };
        }
        if HDR_ROWS.contains(&preset.id) {
            return Ok(Some(asked.unwrap_or(DynamicRange::Hlg)));
        }
        match hdr_asked {
            Some(range) => Err(format!(
                "{} is 8-bit and writes the SDR version; export dynamic_range \"{}\" as \
                 hevc_10bit, av1, av1_webm, vp9_webm, prores_422 or prores_4444",
                preset.id,
                range.as_str()
            )),
            None => Ok(Some(DynamicRange::Sdr)),
        }
    }
}
