let url = URL(fileURLWithPath: CommandLine.arguments[1])
let sem = DispatchSemaphore(value: 0)
Task.detached {
    let asset = AVURLAsset(url: url, options: [AVURLAssetPreferPreciseDurationAndTimingKey: true])
    do {
        let d = try await asset.load(.duration)
        print("duration", d.seconds, d.isNumeric)
    } catch { print("duration error", error) }
    let v = (try? await asset.loadTracks(withMediaType: .video)) ?? []
    print("video tracks", v.count)
    sem.signal()
}
sem.wait()
if let s = CGImageSourceCreateWithURL(url as CFURL, nil) {
    print("imageio count", CGImageSourceGetCount(s), CGImageSourceGetType(s) as Any)
}

